def date_pattern():
    return r'(?:January|February|March|April|May|June|July|August|September|October|November|December)\s+\d{1,2}(?:st|nd|rd|th)?(?:,)?\s+\d{4}|\d{4}-\d{2}-\d{2}'

def normalize_date(value):
    value = value.strip()
    if re.fullmatch(r'\d{4}-\d{2}-\d{2}', value):
        return value
    match = re.fullmatch(r'(January|February|March|April|May|June|July|August|September|October|November|December)\s+(\d{1,2})(?:st|nd|rd|th)?(?:,)?\s+(\d{4})', value)
    if match is None:
        return None
    months = {'January':'01','February':'02','March':'03','April':'04','May':'05','June':'06','July':'07','August':'08','September':'09','October':'10','November':'11','December':'12'}
    return match.group(3) + '-' + months[match.group(1)] + '-' + match.group(2).zfill(2)

def sentences(text):
    result = []
    for match in re.finditer(r'[^.!?]+[.!?]?', text):
        value = match.group(0).strip()
        if value:
            result.append(value)
    return result

def person_pattern():
    return r'([A-Z][A-Za-z\'’-]*(?:\s+[A-Z][A-Za-z\'’-]*){0,3})'

def named_institutions(sentence):
    result = []
    named = r'\b([A-Z][A-Za-z&.\'’-]*(?:\s+[A-Z][A-Za-z&.\'’-]*){0,7}\s+(?:University|College|School))\b'
    for match in re.finditer(named, sentence):
        value = match.group(1).strip()
        if value not in result:
            result.append(value)
    classified = r'\b([A-Z][A-Za-z&.\'’-]*(?:\s+[A-Z][A-Za-z&.\'’-]*){0,7})\s+(?:is|was)\s+(?:an?\s+)?(?:university|college|school)\b'
    for match in re.finditer(classified, sentence):
        value = match.group(1).strip()
        if value not in result:
            result.append(value)
    return result

def event_window(sentence, start):
    tail = sentence[start:]
    boundary = r'(?:;|,\s*and|\band)\s+' + person_pattern() + r'\s+(?:was|is|has|had|became|began|started|attended|enrolled)\b'
    match = re.search(boundary, tail[1:])
    if match is not None:
        return tail[:match.start() + 1]
    return tail

def time_record(window, channel):
    date = date_pattern()
    ranges = list(re.finditer(r'\bfrom\s+(' + date + r')\s+(?:to|through|until)\s+(' + date + r')', window))
    ranges += list(re.finditer(r'\bbetween\s+(' + date + r')\s+and\s+(' + date + r')', window))
    if len(ranges) == 1:
        start = normalize_date(ranges[0].group(1))
        end = normalize_date(ranges[0].group(2))
        if start is not None and end is not None:
            return {'form':'closed_interval','start_date':start,'end_date':end,'as_of_date':None}
    if len(ranges) > 1:
        return None
    since = list(re.finditer(r'\bsince\s+(' + date + r')', window))
    if len(since) == 1:
        start = normalize_date(since[0].group(1))
        if start is not None:
            return {'form':'ongoing_since','start_date':start,'end_date':None,'as_of_date':None}
    if len(since) > 1:
        return None
    as_of = list(re.finditer(r'\bas of\s+(' + date + r')', window))
    if len(as_of) == 1:
        value = normalize_date(as_of[0].group(1))
        if value is not None:
            return {'form':'active_on_date','start_date':None,'end_date':None,'as_of_date':value}
    if len(as_of) > 1:
        return None
    onset = list(re.finditer(r'\b(?:began|started|became)\b[^.;]*?\bon\s+(' + date + r')', window))
    if len(onset) == 1:
        value = normalize_date(onset[0].group(1))
        if value is not None:
            return {'form':'onset_only','start_date':value,'end_date':None,'as_of_date':None}
    if len(onset) > 1:
        return None
    if channel == 'attendance':
        active = list(re.finditer(r'\b(?:was|is)\s+(?:regularly\s+)?attending\s+(?:regular\s+)?classes\b[^.;]*?\bon\s+(' + date + r')', window))
        if len(active) == 1:
            value = normalize_date(active[0].group(1))
            if value is not None:
                return {'form':'active_on_date','start_date':None,'end_date':None,'as_of_date':value}
    return None

def add_institution(rows, institution, quote):
    for row in rows:
        if row.get('institution') == institution:
            witness = {'field':'facts','quote':quote}
            if witness not in row['witnesses']:
                row['witnesses'].append(witness)
            return
    rows.append({'institution':institution,'witnesses':[{'field':'facts','quote':quote}]})

def make_event(person, institution, timing, quote):
    return {'person':person,'institution':institution,'form':timing['form'],'start_date':timing['start_date'],'end_date':timing['end_date'],'as_of_date':timing['as_of_date'],'witnesses':[{'field':'facts','quote':quote}]}

def channel_patterns(channel, institution):
    person = person_pattern()
    place = re.escape(institution)
    aux = r'(?:was|is|has been|had been)'
    if channel == 'enrollments':
        return [person + r'\s+(?:(?:was|is|has been|had been)\s+(?:currently\s+)?enrolled|became\s+enrolled)\s+(?:at|in)\s+' + place + r'\b', person + r'\s+' + aux + r'\s+(?:regularly\s+)?attending\s+(?:regular\s+)?classes\s+(?:,?\s+)?and\s+(?:(?:was|is)\s+)?enrolled\s+(?:at|in)\s+' + place + r'\b']
    return [person + r'\s+' + aux + r'\s+(?:regularly\s+)?attending\s+(?:regular\s+)?classes\s+(?:at|in)\s+' + place + r'\b', person + r'\s+' + aux + r'\s+(?:currently\s+)?enrolled\s+(?:at|in)\s+' + place + r'\b\s*(?:,?\s+and\s+)(?:(?:was|is)\s+)?(?:regularly\s+)?attending\s+(?:regular\s+)?classes\b', person + r'\s+' + aux + r'\s+(?:regularly\s+)?attending\s+(?:regular\s+)?classes\s*(?:,?\s+and\s+)(?:(?:was|is)\s+)?enrolled\s+(?:at|in)\s+' + place + r'\b']

def scan_channel(sentence, institutions, channel):
    records = []
    matched = False
    invalid = False
    for institution in institutions:
        for pattern in channel_patterns(channel, institution):
            for match in re.finditer(pattern, sentence):
                matched = True
                window = event_window(sentence, match.start())
                timing = time_record(window, 'attendance' if channel == 'attendance' else 'enrollment')
                if timing is None:
                    invalid = True
                else:
                    record = make_event(match.group(1), institution, timing, sentence)
                    if record not in records:
                        records.append(record)
    return {'records':records,'matched':matched,'invalid':invalid}

def apply(inputs, premises):
    facts = inputs.get('facts') if type(inputs) is dict else None
    if type(facts) is not str or not facts:
        return {'views':[{'extraction_status':'unread','institutions':None,'enrollments':None,'attendance':None,'witnesses':[]}]}
    parts = sentences(facts)
    institutions = []
    identities = []
    for sentence in parts:
        for institution in named_institutions(sentence):
            add_institution(institutions, institution, sentence)
            if institution not in identities:
                identities.append(institution)
    enrollments = []
    attendance = []
    ambiguous = False
    for sentence in parts:
        local_institutions = named_institutions(sentence)
        if re.search(r'\b(?:university|college|school)\b', sentence, re.IGNORECASE) and len(local_institutions) == 0:
            ambiguous = True
        enrollment_scan = scan_channel(sentence, identities, 'enrollments')
        attendance_scan = scan_channel(sentence, identities, 'attendance')
        for record in enrollment_scan['records']:
            if record not in enrollments:
                enrollments.append(record)
        for record in attendance_scan['records']:
            if record not in attendance:
                attendance.append(record)
        if re.search(r'\benroll(?:ed|ment|ing)?\b', sentence, re.IGNORECASE):
            if not enrollment_scan['matched'] or enrollment_scan['invalid']:
                ambiguous = True
        if re.search(r'\battend(?:ed|ing|ance)?\b[^.;]*\bclass(?:es)?\b|\bclass(?:es)?\s+attendance\b', sentence, re.IGNORECASE):
            if not attendance_scan['matched'] or attendance_scan['invalid']:
                ambiguous = True
        if re.search(r'\b(?:student|studied|studying|graduated|coursework|campus)\b', sentence, re.IGNORECASE):
            ambiguous = True
        if re.search(r'\bclass(?:es)?\b', sentence, re.IGNORECASE) and not re.search(r'\battend(?:ed|ing|ance)?\b[^.;]*\bclass(?:es)?\b', sentence, re.IGNORECASE):
            ambiguous = True
    witness = [{'field':'facts','quote':facts}]
    if ambiguous:
        return {'views':[{'extraction_status':'unread','institutions':None,'enrollments':None,'attendance':None,'witnesses':witness}]}
    return {'views':[{'extraction_status':'complete','institutions':institutions,'enrollments':enrollments,'attendance':attendance,'witnesses':witness}]}

def teacher_date_source():
    return r'(?:January|February|March|April|May|June|July|August|September|October|November|December)\s+\d{1,2}(?:st|nd|rd|th)?(?:,)?\s+\d{4}|\d{4}-\d{2}-\d{2}'

def teacher_iso(text):
    text = text.strip()
    if re.fullmatch(r'\d{4}-\d{2}-\d{2}', text):
        return text
    row = re.fullmatch(r'(January|February|March|April|May|June|July|August|September|October|November|December)\s+(\d{1,2})(?:st|nd|rd|th)?(?:,)?\s+(\d{4})', text)
    if row is None:
        return None
    numbers = {'January':'01','February':'02','March':'03','April':'04','May':'05','June':'06','July':'07','August':'08','September':'09','October':'10','November':'11','December':'12'}
    return row.group(3) + '-' + numbers[row.group(1)] + '-' + row.group(2).zfill(2)

def teacher_sentences(text):
    rows = []
    for match in re.finditer(r'[^.!?]+[.!?]?', text):
        item = match.group(0).strip()
        if item:
            rows.append(item)
    return rows

def teacher_person():
    return r'([A-Z][A-Za-z\'’-]*(?:\s+[A-Z][A-Za-z\'’-]*){0,3})'

def teacher_institutions(sentence):
    rows = []
    suffix_name = r'\b([A-Z][A-Za-z&.\'’-]*(?:\s+[A-Z][A-Za-z&.\'’-]*){0,7}\s+(?:University|College|School))\b'
    for match in re.finditer(suffix_name, sentence):
        name = match.group(1).strip()
        if name not in rows:
            rows.append(name)
    classification = r'\b([A-Z][A-Za-z&.\'’-]*(?:\s+[A-Z][A-Za-z&.\'’-]*){0,7})\s+(?:is|was)\s+(?:an?\s+)?(?:university|college|school)\b'
    for match in re.finditer(classification, sentence):
        name = match.group(1).strip()
        if name not in rows:
            rows.append(name)
    return rows

def teacher_units(sentence):
    rows = []
    start = 0
    boundary = r'(?:;|,\s*and|\band)\s+' + teacher_person() + r'\s+(?:was|is|has|had|became|began|started|attended|enrolled)\b'
    for match in re.finditer(boundary, sentence):
        cut = match.start()
        first = sentence[start:cut].strip(' ,;')
        if first:
            rows.append(first)
        start = cut
        prefix = re.match(r'(?:;|,\s*and|\band)\s*', sentence[start:])
        if prefix is not None:
            start += prefix.end()
    last = sentence[start:].strip(' ,;')
    if last:
        rows.append(last)
    return rows

def teacher_time(unit, kind):
    date = teacher_date_source()
    intervals = list(re.finditer(r'\bfrom\s+(' + date + r')\s+(?:to|through|until)\s+(' + date + r')', unit))
    intervals += list(re.finditer(r'\bbetween\s+(' + date + r')\s+and\s+(' + date + r')', unit))
    if len(intervals) == 1:
        left = teacher_iso(intervals[0].group(1))
        right = teacher_iso(intervals[0].group(2))
        if left is not None and right is not None:
            return {'form':'closed_interval','start_date':left,'end_date':right,'as_of_date':None}
    if len(intervals) > 1:
        return None
    since = list(re.finditer(r'\bsince\s+(' + date + r')', unit))
    if len(since) == 1:
        value = teacher_iso(since[0].group(1))
        if value is not None:
            return {'form':'ongoing_since','start_date':value,'end_date':None,'as_of_date':None}
    if len(since) > 1:
        return None
    dated_state = list(re.finditer(r'\bas of\s+(' + date + r')', unit))
    if len(dated_state) == 1:
        value = teacher_iso(dated_state[0].group(1))
        if value is not None:
            return {'form':'active_on_date','start_date':None,'end_date':None,'as_of_date':value}
    explicit_start = list(re.finditer(r'\b(?:began|started|became)\b[^.;]*?\bon\s+(' + date + r')', unit))
    if len(explicit_start) == 1:
        value = teacher_iso(explicit_start[0].group(1))
        if value is not None:
            return {'form':'onset_only','start_date':value,'end_date':None,'as_of_date':None}
    if kind == 'attendance':
        active = list(re.finditer(r'\b(?:was|is)\s+(?:regularly\s+)?attending\s+(?:regular\s+)?classes\b[^.;]*?\bon\s+(' + date + r')', unit))
        if len(active) == 1:
            value = teacher_iso(active[0].group(1))
            if value is not None:
                return {'form':'active_on_date','start_date':None,'end_date':None,'as_of_date':value}
    return None

def teacher_add_institution(rows, name, quote):
    witness = {'field':'facts','quote':quote}
    for row in rows:
        if row['institution'] == name:
            if witness not in row['witnesses']:
                row['witnesses'].append(witness)
            return
    rows.append({'institution':name,'witnesses':[witness]})

def teacher_record(person, institution, timing, quote):
    return {'person':person,'institution':institution,'form':timing['form'],'start_date':timing['start_date'],'end_date':timing['end_date'],'as_of_date':timing['as_of_date'],'witnesses':[{'field':'facts','quote':quote}]}

def teacher_roles(unit, institution):
    person = teacher_person()
    place = re.escape(institution)
    aux = r'(?:was|is|has been|had been)'
    enrollment = [person + r'\s+(?:(?:was|is|has been|had been)\s+(?:currently\s+)?enrolled|became\s+enrolled)\s+(?:at|in)\s+' + place + r'\b', person + r'\s+' + aux + r'\s+(?:regularly\s+)?attending\s+(?:regular\s+)?classes\s*(?:,?\s+and\s+)(?:(?:was|is)\s+)?enrolled\s+(?:at|in)\s+' + place + r'\b']
    attendance = [person + r'\s+' + aux + r'\s+(?:regularly\s+)?attending\s+(?:regular\s+)?classes\s+(?:at|in)\s+' + place + r'\b', person + r'\s+' + aux + r'\s+(?:currently\s+)?enrolled\s+(?:at|in)\s+' + place + r'\b\s*(?:,?\s+and\s+)(?:(?:was|is)\s+)?(?:regularly\s+)?attending\s+(?:regular\s+)?classes\b', person + r'\s+' + aux + r'\s+(?:regularly\s+)?attending\s+(?:regular\s+)?classes\s*(?:,?\s+and\s+)(?:(?:was|is)\s+)?enrolled\s+(?:at|in)\s+' + place + r'\b']
    return {'enrollment':enrollment,'attendance':attendance}

def teacher_parse_unit(unit, quote, identities):
    enrollments = []
    attendance = []
    enrollment_match = False
    attendance_match = False
    invalid = False
    for institution in identities:
        roles = teacher_roles(unit, institution)
        for pattern in roles['enrollment']:
            for match in re.finditer(pattern, unit):
                enrollment_match = True
                timing = teacher_time(unit, 'enrollment')
                if timing is None:
                    invalid = True
                else:
                    row = teacher_record(match.group(1), institution, timing, quote)
                    if row not in enrollments:
                        enrollments.append(row)
        for pattern in roles['attendance']:
            for match in re.finditer(pattern, unit):
                attendance_match = True
                timing = teacher_time(unit, 'attendance')
                if timing is None:
                    invalid = True
                else:
                    row = teacher_record(match.group(1), institution, timing, quote)
                    if row not in attendance:
                        attendance.append(row)
    return {'enrollments':enrollments,'attendance':attendance,'enrollment_match':enrollment_match,'attendance_match':attendance_match,'invalid':invalid}

def apply(inputs, premises):
    facts = inputs.get('facts') if type(inputs) is dict else None
    if type(facts) is not str or not facts:
        return {'views':[{'extraction_status':'unread','institutions':None,'enrollments':None,'attendance':None,'witnesses':[]}]}
    source_sentences = teacher_sentences(facts)
    institutions = []
    identities = []
    for sentence in source_sentences:
        for name in teacher_institutions(sentence):
            teacher_add_institution(institutions, name, sentence)
            if name not in identities:
                identities.append(name)
    enrollments = []
    attendance = []
    unread = False
    for sentence in source_sentences:
        if re.search(r'\b(?:university|college|school)\b', sentence, re.IGNORECASE) and len(teacher_institutions(sentence)) == 0:
            unread = True
        for unit in teacher_units(sentence):
            parsed = teacher_parse_unit(unit, sentence, identities)
            for row in parsed['enrollments']:
                if row not in enrollments:
                    enrollments.append(row)
            for row in parsed['attendance']:
                if row not in attendance:
                    attendance.append(row)
            enrollment_cue = re.search(r'\benroll(?:ed|ment|ing)?\b', unit, re.IGNORECASE) is not None
            attendance_cue = re.search(r'\battend(?:ed|ing|ance)?\b[^.;]*\bclass(?:es)?\b|\bclass(?:es)?\s+attendance\b', unit, re.IGNORECASE) is not None
            if enrollment_cue and not parsed['enrollment_match']:
                unread = True
            if attendance_cue and not parsed['attendance_match']:
                unread = True
            if parsed['invalid']:
                unread = True
            if re.search(r'\b(?:student|studied|studying|graduated|coursework|campus)\b', unit, re.IGNORECASE):
                unread = True
            if re.search(r'\bclass(?:es)?\b', unit, re.IGNORECASE) and not attendance_cue:
                unread = True
    witnesses = [{'field':'facts','quote':facts}]
    if unread:
        return {'views':[{'extraction_status':'unread','institutions':None,'enrollments':None,'attendance':None,'witnesses':witnesses}]}
    return {'views':[{'extraction_status':'complete','institutions':institutions,'enrollments':enrollments,'attendance':attendance,'witnesses':witnesses}]}
